WFJ.Data.add("gossip", {
  ["f50380244bff8657"] = { "時が来れば、奥方様。時が来ればすべて明らかになります。主は今まさに目覚めつつあります。空を見上げなさい。Brood of Nozdormuが戻ってきたのですから。", "." },
  ["f5070ae8754e63c1"] = { "実によい質問だ、{class}。最後に聞いた話では、Allianceは戦への備えに必要なcopper barsを$1998w本中$1997w本、iron barsを$2003w本中$2002w本、thorium barsを$2012w本中$2011w本、精錬し終えたそうだ。", "." },
  ["f50c040e11b7a57d"] = { "お前は私が教えられることをすべて学んだ、{name}。ここで学んだことを携えて、自分自身のペットを選ぶときだ。\n\nさあ、受け取れ、{name}。これよりお前に、獣を手なずける力と、思うままに呼び出し、送り返す力を与えよう。新たな技を誇りとともに使え。お前はそれを勝ち取ったのだ。", "." },
  ["f50e0dde4a062014"] = { "MoorantaならSkinningを学ぶ手助けをしてくれる。彼女は中段の高台にあるThunder Bluff Armorersのすぐ外にいる。", "." },
  ["f51035469536be37"] = { "Ishnu... Oshalan thara dormil... Anu'dorin...", "." },
  ["f51aa128e297e1bd"] = { "お前は、私が今まで見たどんな松明よりも輝いているよ、{name}。だから、誇りに思うべきだ。\n\nこの先に進むなら、自然の力はお前の命令に従い、我らの同胞は知恵と導きをお前に求めるだろう。これを受け取ってくれたまえ。お前の新しいトーテムを最初に祝わせてくれ。", "." },
  ["f51c64aafae72e4c"] = { "よくぞ聞いてくれた……ちょうどその報告が届いたところだ。今のところAllianceは、light leatherを$2061w枚中$2060w枚、medium leatherを$2064w枚中$2063w枚、thick leatherの皮を$2071w枚中$2069w枚集めている。", "." },
  ["f51e8d3396c29879"] = { "ローブが出来上がったよ、{name}。", "." },
  ["f5320b953603b7b0"] = { "気をつけ! Ahn'Qirajの戦争物資はすべて確認済みで、現在Cenarion Holdへ輸送中であります、閣下! 最後の分は$2113w日以内に到着するとのことです。それが済んで、誰かがあそこの銅鑼を鳴らして門を開けば、あの虫どもにとびきりの戦いを見せてやると保証します!", "." },
  ["f532949f52d40710"] = { "狼の皮は十分に集まった。じきに騎兵隊の出撃準備が整うぞ！十分な数の羊を厩舎に入れたら、また私に話しかけてくれ。", "." },
  ["f533bd13f2743bed"] = { "旅の手助けとして、何ができるでしょうか？", "." },
  ["f5367e4b7b73da17"] = { "深き破滅", "." },
  ["f53dea4e0237027e"] = { "E'koってのは超自然の力の定まらない形で、Jujuはそれを凝縮した精髄だ。強い呪文を使えば、俺はE'koをJujuに変えられる。Jujuになっちまえば、あんたはCache of Mau'ariを使って、その力を自分に映し取れるってわけさ。", "." },
  ["f55c5d42b7a92173"] = { "パパ！帰ってきたんだね！", "." },
  ["f5628678fffdcb4f"] = { "よく来た、{class}。Ahn'Qirajの戦への備えについて尋ねに来たのだろう。我々には多大な助力が必要だ。\n\n戦への備えとは、Ahn'Qirajに巣食うSilithidとその主人たちとの、迫り来る戦に備えるためのHordeとAllianceの共同の取り組みだ。OrgrimmarのValley of Spiritsでは、戦のための物資を作るべく膨大な量の品を集めており、その収集の仕事でこそ、そなたの手を借りたいのだ。\n\n力添えの件で、我々の司令官と話をしてもらえないだろうか？", "." },
  ["f56c162b07aaede1"] = { "そしていよいよ戦が近づいてきた。残っているのは、この品々と武器をすべてSilithusのCenarion Holdへ送ることだけで、それも$2113w日以内には終わる。あとは誰か勇敢な者が、あのAhn'Qirajの門のそばにある銅鑼を鳴らして門を開き、戦を始めなきゃならん。", "." },
  ["f56d58cbf3c1f03d"] = { "ようこそ、同胞よ。修練のために来たのであれば、喜んでお教えしましょう。\n\nCenarion Circleの内部に対立があるという噂もありますが、そのような無責任な話に耳を貸してはいけません。我らの大ドルイド、Fandral Staghelmが、我々とTeldrassilのすべてを栄光へと導いてくださるのです！", "." },
  ["f56de0545868db09"] = { "まあ、「払う」ってのは一番いい言い方じゃないかもしれないな。いいか、あいつの腹の中に閉じ込められていたとき、俺は考えたんだ。\n\nこの生き物は熱く燃えるマグマの中で暮らしているのに、炎で少しも傷つかない！\n\nこいつらの傷ひとつない皮を手に入れられさえすればな。それをEverlookにいる親しい友、Malyfous Darkhammerのところへ持っていける。こんな獣の皮から何かを作れる者がいるとすれば、それは奴だ。", "." },
  ["f57247c0e9bd90e7"] = { "{name}、浄化のトーテムを作ったぞ。", "." },
  ["f573156f252ef43d"] = { "<Bolvarはあなたをじっと見つめている。>", "." },
  ["f5736298f8b9ee50"] = { "確かに再装填には時間がかかるが、こいつはどんな鎧にも俺の拳ほどの穴を開けてくれるぜ。", "." },
  ["f5739fbd011b0243"] = { "Fishingってのは本当に心地いいもんだ。だろう？この幸せな境地は、俺の師匠、世界一の釣り人であるNat Pagleのおかげさ。奴のことを聞いたことはあるかい？\n\n悟りを求めているなら、その道を示してくれるのはNat Pagleだ。", "." },
  ["f5810adbd97500eb"] = { "またしても見事だ、{name}。お前ほど素質のある若いウォーロックを見たのは、ずいぶん久しぶりだ。安心しろ、私はこれからもお前の成長を見守り、来るべき試練に備えさせ、力を貸してやろう。\n\n今は、新たに従えたsuccubusを召喚する呪文を見せてやろう。", "." },
  ["f586e79f14893039"] = { "中央へテレポートで戻る", "." },
  ["f58b2e34a6ac578a"] = { "Vaelastraszよ、この世界が黒の竜族のものとなったとき、貴様の竜族は終焉を迎えるのだ。", "." },
  ["f58cfa5748517548"] = { "Hakkarに血と魂を！ハハハハ！", "." },
  ["f58d82f0f4c491b0"] = { "これを取って、飲み干すんだ。", "." },
  ["f58f2133e6126d08"] = { "そうだ、そなただった。Eyeが誤ることはない。\n\n何といっても、そなたはプリーストなのだ。Eyeがそなたにこの恐ろしい記憶を見せたのなら、力あるプリーストであろう。\n\nそなたは贖罪を求めてここへ来た。だが、そなた自身はそのことに気づいてすらいない……そうであろう?", "." },
  ["f59cff7a4bf58727"] = { "428,000 degrees Kraklenheitだ……どうしたんだい、熱いねえ！？", "." },
  ["f59f668670339dfb"] = { "ここでのお前の戦いなど、世界規模の侵攻のほんの塵の一粒にすぎん、小童！お前が相手にしている力を思い知る時だ！", "." },
  ["f5a1c3656f8dee8a"] = { "こんなところで何をしているんだ？", "." },
  ["f5a4711844ed5a7e"] = { "Alterac Mountainsに抱かれたDalaran Cityへの便は、ここから乗ってください。", "." },
  ["f5a72f36a1a99c8e"] = { "これの結合構造が弱いことに注目しなさい。詠唱は必ず最後まで終えること。さもないと、こういう結果になります。", "." },
  ["f5abb388b78855b0"] = { "おやまあ、なんと驚いた！また失敗ですか！？でも、どうしてです、偉大なるお方？？", "." },
  ["f5b2ee6b6f6bae14"] = { "自信があるようだな。ならば、腕試しをしても構わないだろう？", "." },
  ["f5b978bdbbc4521e"] = { "{name}、私の務めは終わったので、これにて失礼するよ。幸運を、友よ。Bell、Wheel、Candleを動かし続けるのを忘れないでくれ！", "." },
  ["f5bec52007ff9685"] = { "%sはため息をついた……", "." },
  ["f5cf13e5ef7bcd29"] = { "Crusadeを作ったのは、High General Abbendis、High Inquisitor Isillien、そしてHighlord Mograineだ。興った当初、Crusadeは高潔な組織だった。今そなたが目にしているような狂気と常軌を逸した狂信は存在しなかった。堕落の歯車が回り始めたのは、大十字軍長として知られる者が現れてからのことだ。", "." },
  ["f5d26f82c26f8e7c"] = { "{class}よ、Warsong Gulchでの戦いにおいて、得られる限りの助力が必要だと言うことを、我々は恥とは思わない。だが、あなたが力を貸してくれるのなら、今こそ過去のどの時よりも大きな誉れを得られるときだ。それに、我々のために尽くしてくれれば、Silverwing Sentinelsもきっとあなたの働きをより好意的に見てくれるだろう。戦いに加わってくれるか？", "." },
  ["f5deca345165a6dc"] = { "この悪夢は終わることがあるのか？！どうしても目を覚ませない！", "." },
  ["f5eb8d533ee0b7dd"] = { "ごきげんよう、{class}。戦への備えに力を貸そうと関心を持ってくれて嬉しく思う。ここの収集係たちは、そのときが来たときに備えられるよう、さまざまな物資の備蓄を集める手配をしている。\n\n私が任されているのは、Ahn'Qirajでの戦いに関わる者たちのために蓄えるbaked salmonを$2106w個集めることだ。最後に数えたときには、$2105w集まっていた。", "." },
  ["f5ee7552a36bc30b"] = { "たいていはいつも通りだ。murlocの襲撃に、ときどきScarlet Crusadeとの小競り合い。Forsakenとしての生き方にどうしても馴染めないパラディンどももいる。兄弟に刃を向けた奴らを始末しなければならないことが、あまりにも多い。\n\n何より最悪なのは、心を失った下僕がうろうろと近づきすぎたときだ。murlocなら朝から晩まででも殺せるが、私が滅ぼさなければならなかったscourgeの中には、かつての友もいた。家族だった者さえいた。\n\nどこかの見知らぬ冒険者より、私の手で始末してやるほうがいい。だが、それでもやはり胸が痛む。", "." },
  ["f5f4190a7d71d4e2"] = { "Dire Maulという場所のことを聞いたことがあるか？", "." },
  ["f5f9b8d891b84a71"] = { "よし、兄弟、次はsaptaだ……俺のそばを離れるなよ。", "." },
  ["f5fbb234b3f530dc"] = { "そなたに授けるべき知識は多い、{class}。誉れをもって狩ることを学ばねばならない。", "." },
